INSERT INTO `email_template` (`id`, `subject`, `contents`, `signature`, `created_at`, `updated_at`) VALUES
(1, 'Reminder - Progress Report', 'Dear *name*\r\n<br>\r\nGreetings from ORS...\r\n<br>\r\nWe would like to take your attention for the progress report deadline of the grant titled : <b>*grant_title*</b> grant No. <b>*grant_no*</b> before <b>*duedate*</b>. kindly arrange to: <br>\r\n<ul>\r\n<li>Fill the Required Fields.</li>\r\n<li>Make Sure the Report will Be Align with the Project Scope of Work.</li>\r\n<li>Get the College Approval.</li>\r\n</ul>\r\n<br>\r\nThe template is available at <template>.\r\n<br>\r\n*Any delay in submitting the report will affect releasing and availability of the next year funds.\r\n<br>\r\nThanks in Advance', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Email Signature</title>\n<style>\n  .email-signature {\n    width: 100%;  \n    font-family: Arial, sans-serif;\n  }\n  .logo {\n    width: 350px; /* Adjust this according to your logo\'s size */\n    height: 45px;\n  }\n  \n    .logo2 {\n    width: auto; /* Adjust this according to your logo\'s size */\n    height: 45px;\n  }\n  \n  .social {\n    width: 7px; /* Adjust this according to your logo\'s size */\n    height:7px;\n	margin-right:10px;\n  }\n   .micro-text-2 {\n    font-size: 10px;\n    line-height: 1.2;\n    margin: 2px 0;\n	color: #800000;\n  }\n  .micro-text {\n    font-size: 10px;\n    line-height: 1.2;\n    margin: 2px 0;\n \n  }\n</style>\n</head>\n<body>\n<br>\n\n<table class=\"email-signature\" cellpadding=\"0\" cellspacing=\"0\">\n  <tr>\n    <td width=\"25%\">\n      <img src=\"cid:logo\" alt=\"Logo\" class=\"logo\">\n    </td>\n    <td width=\"35%\">\n      <p class=\"micro-text\">Research Support Department (Grants & Contracts) | Post-Award Team  | Research Complex Building (H10)</p>\n      <p class=\"micro-text\">1st Floor, Room G209, Office F027</p>\n      <p class=\"micro-text\">www.qu.edu.qa |  +974 4403 7126 |  ros-submissions@qu.edu.qa</p>\n      <p class=\"micro-text\">\n        <img src=\"cid:linkedin\" alt=\"LinkedIn\" class=\"social\">\n        <img src=\"cid:twitter\" alt=\"Twitter\" class=\"social\">\n        <img src=\"cid:facebook\" alt=\"Facebook\" class=\"social\">\n        <img src=\"cid:instagram\" alt=\"Instagram\" class=\"social\">\n        <img src=\"cid:youtube\" alt=\"YouTube\" class=\"social\">\n      </p>\n    </td>\n    <td width=\"40%\"></td>\n  </tr>\n<br>\n  <tr>\n    <td colspan=\"3\">\n      <img src=\"cid:iso\" alt=\"ISO Logo\" class=\"logo2\">\n      <p class=\"micro-text\"><b>Our Vision: </b>To be regionally recognized for distinctive excellence in education and research, an institution of choice for students and scholars and a catalyst for the sustainable socio-economic development of Qatar.</p>\n    </td>\n  </tr>\n  \n   <tr>\n    <td colspan=\"3\">\n      \n      <p class=\"micro-text-2\"><b>Disclaimer: </b>\n	 \n	[1] This inbox is not monitored. If you have inquiries or feedback email at ros-submissions@qu.edu.qa\n	  [2] The System is only available on QU network.\n	  \n	  </p>\n    </td>\n  </tr>\n  \n</table>\n</body>\n</html>', '0000-00-00', '2024-03-21'),
(2, 'Invitation to Review', 'Dear *name*,\n<br><br>\nGreetings from Office of Research Support at Qatar University (QU) .\n<p>\nWe are reaching out to request your assistance in reviewing the progress report of, Titled: <b>*grant_title*</b> reference No. <b>*old_project_id*</b> in the Research Tracking System (RTS). The system is accessible at https://lrts.qu.edu.qa\n<p>\nIf you are unavailable, we kindly ask that you notify the committee chair within <b>one week</b> of receiving this email.\n\nShould you have any scheduling conflicts or require additional information, please feel free to reach out. Your expertise and insights are greatly valued, and we appreciate your support in this review process.\n<p>Thank you very much.\n</p>\n<br>\n\n<br>', '<table style=\"background-color: white; padding: 10px; border-radius: 5px; border: 0; \">\n    <tr>\n      <td style=\"font-family: Arial, Helvetica, sans-serif; font-size: 13px; font-weight: bold; color: #333333; line-height: 1.4; padding: 0; margin: 0;\">This is a system generated email and doesn\'t require a signature. </td>\n    </tr>\n    <tr>\n      <td style=\"font-family: Arial, Helvetica, sans-serif; font-size: 13px;   color: #333333; line-height: 1.4; padding: 0; margin: 0;\">If you experience any issues contact us at <a href=\"mailto:ros-submissions@qu.edu.qa\">ros-submissions@qu.edu.qa</a> </td>\n    </tr>\n    <tr>\n      <td style=\"font-family: Arial, Helvetica, sans-serif; font-size: 13px; color: #f30d0d; line-height: 1.4; padding: 0; margin: 0;\">Please do not reply to this email as this account is meant for sending announcements only.</td>\n    </tr>\n  </table>', NULL, '2024-11-04'),
(3, 'Remaining Project Budget', 'Dear <b>*name*</b>,\n<br>\n<br>\nThis is a kind reminder that your project with identification number <b>*project_name*</b> has Qar <b>*balance*</b> remaining. \n<br>\n<br>\nRegards, <br>', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Email Signature</title>\n<style>\n  .email-signature {\n    width: 100%;  \n    font-family: Arial, sans-serif;\n  }\n  .logo {\n    width: 350px; /* Adjust this according to your logo\'s size */\n    height: 45px;\n  }\n  \n    .logo2 {\n    width: auto; /* Adjust this according to your logo\'s size */\n    height: 45px;\n  }\n  \n  .social {\n    width: 7px; /* Adjust this according to your logo\'s size */\n    height:7px;\n	margin-right:10px;\n  }\n   .micro-text-2 {\n    font-size: 10px;\n    line-height: 1.2;\n    margin: 2px 0;\n	color: #800000;\n  }\n  .micro-text {\n    font-size: 10px;\n    line-height: 1.2;\n    margin: 2px 0;\n \n  }\n</style>\n</head>\n<body>\n<br>\n\n<table class=\"email-signature\" cellpadding=\"0\" cellspacing=\"0\">\n  <tr>\n    <td width=\"25%\">\n      <img src=\"cid:logo\" alt=\"Logo\" class=\"logo\">\n    </td>\n    <td width=\"35%\">\n      <p class=\"micro-text\">Research Support Department (Grants & Contracts) | Post-Award Team  | Research Complex Building (H10)</p>\n      <p class=\"micro-text\">1st Floor, Room G209, Office F027</p>\n      <p class=\"micro-text\">www.qu.edu.qa |  +974 4403 7126 |  ros-submissions@qu.edu.qa</p>\n      <p class=\"micro-text\">\n        <img src=\"cid:linkedin\" alt=\"LinkedIn\" class=\"social\">\n        <img src=\"cid:twitter\" alt=\"Twitter\" class=\"social\">\n        <img src=\"cid:facebook\" alt=\"Facebook\" class=\"social\">\n        <img src=\"cid:instagram\" alt=\"Instagram\" class=\"social\">\n        <img src=\"cid:youtube\" alt=\"YouTube\" class=\"social\">\n      </p>\n    </td>\n    <td width=\"40%\"></td>\n  </tr>\n<br>\n  <tr>\n    <td colspan=\"3\">\n      <img src=\"cid:iso\" alt=\"ISO Logo\" class=\"logo\">\n      <p class=\"micro-text\"><b>Our Vision: </b>To be regionally recognized for distinctive excellence in education and research, an institution of choice for students and scholars and a catalyst for the sustainable socio-economic development of Qatar.</p>\n    </td>\n  </tr>\n  \n   <tr>\n    <td colspan=\"3\">\n      \n      <p class=\"micro-text-2\"><b>Disclaimer: </b>\n	 \n	[1] This inbox is not monitored. If you have inquiries or feedback email at ros-submissions@qu.edu.qa\n	  [2] The System is only available on QU network.\n	  \n	  </p>\n    </td>\n  </tr>\n  \n</table>\n</body>\n</html>', NULL, NULL),
