(34, '0', '0', '0', NULL, 75, 48, 'pending', 5, 5, 5, NULL, 'Already published two papers in QI journals during the 1st year, and conference papers already submitted and accepted for participation in ACS/RSC’24 and IGC2024 conferences.', NULL, -1, 1, NULL, '2024-12-16 07:11:04', '2024-12-16 07:11:56', 4, NULL),
(35, '0', '0', '0', NULL, 75, 49, 'pending', 4, 4, 5, NULL, NULL, NULL, -1, 1, NULL, '2024-12-16 14:08:31', '2024-12-16 14:08:49', 5, NULL),
(36, '0', '0', '0', NULL, 70, 63, 'pending', 4, 3, 5, 'The project demonstrates advancements in producing a high-quality genomic assembly and annotation, which could serve as a prototype for comparative genomic studies, conservation efforts, and further biological research. However, it does not explicitly indicate progression toward developing a patentable product or open-source software, as the methods used rely on existing tools and software rather than novel innovations in genome assembly or annotation technology.', 'Two manuscripts are currently in preparation, and I look forward to their acceptance in the next reporting period.', NULL, 1, 1, NULL, '2024-12-23 06:13:54', '2024-12-23 06:13:54', 5, 'Despite a significant budget reduction and other related challenges, such as delays in fund release, the investigator managed the resources exceptionally well and achieved remarkable progress.'),
(37, '0', '0', '0', NULL, 39, 51, 'pending', 3, 3, 3, 'The project progess is inline with the its timelines', 'One article is being prepared, the team should make more efforts in publication part.', 'More RAs are employed in the project. more invilvement of studetns is required', -1, 1, NULL, '2024-12-24 06:51:09', '2024-12-24 06:51:09', 5, 'more than 90% of the budget was used.'),
(38, '0', '0', '0', NULL, 39, 66, 'pending', 2, 1, 1, 'The progress made is behind the schedule. the research team is requested to duplicate efforts to meet the project objectives.', 'No publications made out of 3-4 publications committed.', 'One PhD student wa mentionned  at SQU without identification', -1, 1, NULL, '2024-12-24 07:07:33', '2025-01-23 06:18:06', 1, 'No budget use was mentionned for QU team. Requesting actual budget use.'),
