(76, '0', '0', '0', NULL, 73, 291, 'pending', 4, 1, 4, 'First specific aim has been completed and good progress on the immediate aims.', 'Two research article committed but zero achieved', '2 committed thesis project and one achieved.', 1, 1, NULL, '2025-11-25 07:33:21', '2025-11-25 07:33:21', 4, '92% utilization'),
(77, '0', '0', '0', NULL, 75, 250, 'pending', 4, 4, 5, 'There is a good progress in terms of results achieved', 'Two manuscript is now in progress: One in Q1 (manuscript in preparation), and one in Q2 (Draft planned). There is another paper planned in Q2 for 2nd year of project.', 'One B.Sc. Student (senior project). One PhD student (preparing CE on the topic of this project).\r\nOne RA Recruited.', -1, 1, NULL, '2025-12-03 05:01:34', '2025-12-17 06:17:22', 4, NULL),
(78, '0', '0', '0', NULL, 39, 237, 'pending', 3, 2, 4, 'The research team has performed mostly required tasks planned for year 1', 'The LPI cited 6 journal papers in the progress report mostly between \"submitted\" and \"under review\". however, only one of them ( under review is related to project).', '3 Master students and 2 Ras have been presented in the proposal', -1, 1, NULL, '2025-12-06 05:15:00', '2025-12-06 05:15:00', 5, 'more than 90% of the project budget was used. excellent number'),
