(91, '0', '0', '0', NULL, 184, 282, 'pending', 4, 4, 4, NULL, 'One reviewer was published. Another review is under review.', 'Two students were involved.', 1, 1, NULL, '2025-12-15 11:12:41', '2025-12-15 11:16:44', 5, 'Over 60% is utilized.'),
(92, '0', '0', '0', NULL, 184, 257, 'pending', 3, 4, 5, 'IBC and IACUU were granted. IRB is still not ready (at the last stage of review by HMC). It may delay the enrollment process of patients. The completion of the project may be delayed.', 'One review is ready to be submitted.', 'One student was involved.', 0, 1, NULL, '2025-12-15 11:27:07', '2025-12-15 11:27:07', 5, 'All the budget for the first year has been utilized.'),
(93, '0', '0', '0', NULL, 184, 273, 'pending', 5, 5, 5, 'IBC was approved. Project moves smoothly.', 'Two papers have been published.', '2 Master students and 4 undergraduate students were involved.', -1, 1, NULL, '2025-12-15 11:38:42', '2025-12-15 11:38:42', 5, NULL),
(94, '0', '0', '0', NULL, 184, 307, 'pending', 3, 3, 5, 'The animal study has been completed. No paper has been published yet.', 'No publication.', '3 Undergraduate students were involved.', 1, 1, NULL, '2025-12-15 11:53:45', '2025-12-15 11:53:45', 4, NULL),
(95, '0', '0', '0', NULL, 184, 241, 'pending', 5, 3, 5, 'The project is on track. IRB was obtained on time and survey was conducted.', 'No paper has been published yet.', 'Five students were involved in the project.', 1, 1, NULL, '2025-12-15 12:02:23', '2025-12-15 12:02:23', 5, NULL),
